# Summarize branch lengths across all trees to understand evolutionary rates
import re

print("Branch lengths per OG (Cele, Ggal, Mmus, Xlae if present):")
cele_bl, ggal_bl, mmus_bl, xlae_bl = [], [], [], []

for tf in sorted(glob.glob('*.treefile')):
    og = tf.replace('.faa.mafft.clipkit.treefile', '')
    with open(tf) as fh:
        tree = fh.read().strip()
    # Extract branch lengths per taxon
    matches = re.findall(r'(Animals_\w+):([\d.]+)', tree)
    bls = {taxon: float(bl) for taxon, bl in matches}
    print(f"  {og}: {bls}")
    if 'Animals_Cele' in bls: cele_bl.append(bls['Animals_Cele'])
    if 'Animals_Ggal' in bls: ggal_bl.append(bls['Animals_Ggal'])
    if 'Animals_Mmus' in bls: mmus_bl.append(bls['Animals_Mmus'])
    if 'Animals_Xlae' in bls: xlae_bl.append(bls['Animals_Xlae'])

print(f"\nMean branch lengths:")
print(f"  Animals_Cele (C. elegans, nematode): {sum(cele_bl)/len(cele_bl):.4f} (n={len(cele_bl)})")
print(f"  Animals_Ggal (G. gallus, chicken):   {sum(ggal_bl)/len(ggal_bl):.4f} (n={len(ggal_bl)})")
print(f"  Animals_Mmus (M. musculus, mouse):   {sum(mmus_bl)/len(mmus_bl):.4f} (n={len(mmus_bl)})")
if xlae_bl:
    print(f"  Animals_Xlae (X. laevis, frog):      {sum(xlae_bl)/len(xlae_bl):.4f} (n={len(xlae_bl)})")

# Check alignment lengths
print("\nAlignment lengths per OG:")
for f in sorted(glob.glob('*.faa.mafft.clipkit')):
    og = f.replace('.faa.mafft.clipkit', '')
    seqs = {}
    current = None
    with open(f) as fh:
        for line in fh:
            line = line.strip()
            if line.startswith('>'):
                current = line[1:]
                seqs[current] = ''
            else:
                seqs[current] += line
    lengths = {k: len(v) for k, v in seqs.items()}
    print(f"  {og}: {lengths}")

